        UNION { VALUES ?root { wd:Q7687981 wd:Q209555 wd:Q28130460 wd:Q2835766 wd:Q4291913 wd:Q3030799 wd:Q3518150 wd:Q30103009 wd:Q77977466 wd:Q90932929 wd:Q21998744 wd:Q28941860 wd:Q7706224 wd:Q60750752 wd:Q126889901 wd:Q126889895 wd:Q619388 wd:Q65943 wd:Q130278346 wd:Q402478 } BIND(?root AS ?item) }
